"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisTestimonialsContent } from "./components/testimonials/content";
import View2 from "./components/testimonials/variants/03-grid";
const variants={"grid":View2};
export type { ArtemisTestimonialsContent, ArtemisTestimonialsImage, ArtemisTestimonialsQuote } from "./components/testimonials/content";
export interface ArtemisTestimonialsProps { className?: string; variant?: "grid"; /** The words on the testimonials; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisTestimonialsContent>; }
export function ArtemisTestimonials({className,variant="grid",content}:ArtemisTestimonialsProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** A picture, and the words that describe it. */
export interface ArtemisTestimonialsImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** One testimonial: what was said, and who said it. */
export interface ArtemisTestimonialsQuote {
  /** What they said, without quotation marks; marquee, spotlight, grid and vertical add their own. All layouts. */
  quote: string;
  /** Who said it. All layouts. */
  name: string;
  /** Their title and company as one line, such as "Frontend Lead, Workspace". All layouts. */
  role: string;
  /** Their photo. marquee, spotlight, grid and archive, which show the person's initials in its place when you leave it out. */
  avatar?: ArtemisTestimonialsImage;
  /** A short result over the quote, such as "18 days saved". vertical. */
  metric?: string;
}

/** The words on an Artemis testimonials section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisTestimonialsContent {
  /** The short label over the heading; over the quote in spotlight. All layouts. */
  badge: string;
  /** The heading. marquee, grid, archive and vertical. */
  headline?: string;
  /** The heading's second part. marquee and grid reveal it after `headline`, archive starts a new line for it, and vertical runs it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** A sentence beside or under the heading. marquee, grid and archive. */
  subhead?: string;
  /**
   * The testimonials. All layouts. marquee scrolls them in two rows, the first half on top, and eight or more look
   * best; spotlight shows one at a time with a photo button for each, and four look best; grid shows the first one
   * larger; archive pins them in up to three columns; vertical fills three scrolling columns in order, shows the third
   * from 1024px wide, and nine look best.
   */
  quotes: ArtemisTestimonialsQuote[];
  /** The word after the number of quotes, as in "9 dispatches". vertical. */
  countLabel?: string;
  /** A short line beside that count. vertical. */
  note?: string;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { TextReveal } from "./03-grid/text-reveal";
import type { ArtemisTestimonialsContent } from "../content";
const DEFAULT = {
    badge: "Wall of love",
    headline: "Built for teams",
    headlineAccent: "that sweat the details.",
    subhead: "Premium motion, owned source, and a private registry — trusted by founders and platform teams alike.",
    quotes: [
        { quote: "Artemis gave us motion we could never have built in time. The agent primitives alone — streaming, tool calls, thinking states — saved us a full quarter of work, and every interaction feels native.", name: "Morgan Wells", role: "Frontend Lead, Workspace", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Quiet, fast, polished. Our marketing site finally matches the product.", name: "Morgan Park", role: "Head of Design, Group D", avatar: { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" } },
        { quote: "Copy-paste source means no black-box dependency. We read and own every line.", name: "Jordan Stone", role: "Staff Engineer, Group C", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Installed from our private registry in one command. Onboarding new engineers is trivial now.", name: "Liam O'Brien", role: "CTO, Group E", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "The springs feel native. Reviewers assumed we hand-tuned every single interaction in the app.", name: "Casey Shaw", role: "Eng Manager, Group G", avatar: { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" } },
        { quote: "Every block reads perfectly in light and dark. Zero theme bugs filed.", name: "Robin Ellis", role: "Product Designer, Group F", avatar: { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" } },
        { quote: "Feels like the components were designed by someone who actually ships products.", name: "Avery Stone", role: "Founder, Group A", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
    ],
} satisfies ArtemisTestimonialsContent;
/** Up to two initials from a name, shown in place of a missing photo. */
const initials = (name: string) => name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase() ?? "").join("");
export default function TestimonialsGrid({ content }: { content?: Partial<ArtemisTestimonialsContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const reduce = useReducedMotion();
    return (<>
      <div className="art:w-full">
        <section className="art:w-full">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:max-w-2xl">
              <span className="art:inline-flex art:items-center art:rounded-full art:border art:border-border/60 art:bg-background art:px-3 art:py-1 art:font-medium art:text-muted-foreground art:text-xs">
                {copy.badge}
              </span>
              <TextReveal as="h2" text={accent ? [copy.headline, accent] : [copy.headline]} stagger={0.09} yOffset="40%" className="art:mt-5 art:text-balance art:font-sans art:text-foreground art:text-4xl art:font-medium"/>
              <p className="art:mt-4 art:max-w-xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
                {copy.subhead}
              </p>
            </div>
            <div className="art:mt-12 art:columns-1 art:gap-4 art:@min-[640px]/artemis:columns-2 art:@min-[1024px]/artemis:columns-3">
              {copy.quotes.map((item, index) => (<motion.figure key={index} className={`art:mb-4 art:break-inside-avoid art:rounded-2xl art:border art:bg-background art:p-5 ${index === 0 ? "art:border-primary/40" : "art:border-border/60"}`} initial={{ opacity: 0, filter: "blur(6px)", y: 20 }} whileInView={{ opacity: 1, filter: "blur(0px)", y: 0 }} viewport={{ once: true, margin: "-40px" }} transition={reduce ? { duration: 0 } : { duration: 0.5, ease: ARTEMIS_EASE_OUT, delay: Math.min(index, 5) * 0.06 }}>
                <blockquote className={index === 0 ? "art:text-pretty art:text-foreground art:text-base art:@min-[640px]/artemis:text-lg" : "art:text-pretty art:text-foreground art:text-sm"}>
                  {"“"}
                  {item.quote}
                  {"”"}
                </blockquote>
                <figcaption className="art:mt-4 art:flex art:items-center art:gap-3">
                  {item.avatar ? (<img src={item.avatar.src} alt={item.avatar.alt} aria-hidden="true" width="36" height="36" loading="lazy" className="art:size-9 art:shrink-0 art:rounded-full art:border art:border-border/60"/>) : (<span aria-hidden="true" className="art:grid art:size-9 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border/60 art:bg-muted art:font-medium art:text-muted-foreground art:text-xs">
                      {initials(item.name)}
                    </span>)}
                  <div className="art:min-w-0">
                    <p className="art:truncate art:font-medium art:text-foreground art:text-sm">
                      {item.name}
                    </p>
                    <p className="art:truncate art:text-muted-foreground art:text-xs">
                      {item.role}
                    </p>
                  </div>
                </figcaption>
              </motion.figure>))}
            </div>
          </div>
        </section>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { ArtemisWordEntrance } from "../../../../lib/word-entrance";
export interface TextRevealProps { text: string | string[]; as?: "span" | "div" | "p" | "h1" | "h2" | "h3" | "h4"; className?: string; stagger?: number; delay?: number; blur?: number; yOffset?: string | number; amount?: number; whileInView?: boolean; }
export function TextReveal({text, as: Tag = "span", className, stagger = 0.06, delay, blur, yOffset = "24%", amount, whileInView = true}: TextRevealProps) { return <Tag className={className}><ArtemisWordEntrance words={Array.isArray(text) ? text : text.split(/\s+/)} stagger={stagger} delay={delay} blur={blur} yOffset={typeof yOffset === "number" ? yOffset + "px" : yOffset} amount={amount} entered={whileInView ? undefined : true}/></Tag>; }

"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef } from "react";
import { artemisWordMotion, type ArtemisWordMotionOptions } from "./word-motion";
export interface ArtemisWordEntranceProps {
  words: string[];
  className?: string;
  stagger?: number;
  delay?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: ArtemisWordMotionOptions["spring"];
  once?: boolean;
  amount?: number;
  entered?: boolean;
}
export function ArtemisWordEntrance({
  words,
  className = "",
  stagger = 0.055,
  delay = 0,
  blur = 10,
  yOffset = "20%",
  amount = 0.4,
  spring,
  once = true,
  entered: externalEntry,
}: ArtemisWordEntranceProps) {
  const element = useRef<HTMLSpanElement>(null);
  const observed = useInView(element, { once, amount });
  const entered = externalEntry ?? observed;
  const reduced = useReducedMotion() === true;
  return (
    <span ref={element} className={`art:block ${className}`}>
      <span className="art:block">
        {words.map((word, index) => {
          const movement = artemisWordMotion(index, reduced, {
            delay,
            stagger,
            blur,
            yOffset,
            spring,
          });
          return (
            <motion.span
              key={index}
              className="art:inline-block"
              initial={movement.initial}
              // With reduced motion the words land on mount instead of waiting to be seen.
              animate={entered || reduced ? movement.animate : undefined}
              transition={movement.transition}
            >
              {word}
              {index < words.length - 1 && (
                <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                  {"\u00a0"}
                </span>
              )}
            </motion.span>
          );
        })}
      </span>
    </span>
  );
}

// @zeus-internal
import { ARTEMIS_EASE_OUT } from "./ease";
export interface ArtemisWordMotionOptions {
  delay?: number;
  stagger?: number;
  blur?: number;
  yOffset?: string | number;
  spring?: { stiffness?: number; damping?: number; mass?: number };
}
export function artemisWordMotion(
  index: number,
  reduced: boolean,
  { delay = 0, stagger = 0.055, blur = 10, yOffset = "20%", spring }: ArtemisWordMotionOptions = {}
) {
  const offset = delay + index * stagger;
  // The same start with reduced motion, so hydration matches the server; the words then land at once.
  return {
    initial: { opacity: 0, filter: `blur(${blur}px)`, y: yOffset },
    animate: { opacity: 1, filter: "blur(0px)", y: 0 },
    transition: reduced
      ? { duration: 0 }
      : {
          opacity: { duration: 0.7, delay: offset, ease: ARTEMIS_EASE_OUT },
          filter: { duration: 0.9, delay: offset, ease: ARTEMIS_EASE_OUT },
          y: {
            type: "spring" as const,
            stiffness: spring?.stiffness ?? 140,
            damping: spring?.damping ?? 26,
            mass: spring?.mass ?? 1.2,
            delay: offset,
          },
        },
  };
}
